create table if not exists public.purchase_order_documents(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade,document_type text not null default 'vendor_invoice' check(document_type in ('vendor_invoice','packing_slip','receipt','other')),storage_path text not null,file_name text,uploaded_by uuid references public.users(id),created_at timestamptz not null default now());create index if not exists purchase_order_documents_po_idx on public.purchase_order_documents(purchase_order_id,document_type,created_at desc);alter table public.purchase_order_documents enable row level security;create policy "staff read purchase order documents" on public.purchase_order_documents for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));create policy "purchasing staff add documents" on public.purchase_order_documents for insert to authenticated with check(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch') and uploaded_by=(select id from public.users where auth_user_id=auth.uid() and active=true limit 1));insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('vendor-invoices','vendor-invoices',false,10485760,array['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf']) on conflict (id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;create policy "staff upload vendor invoices" on storage.objects for insert to authenticated with check(bucket_id='vendor-invoices' and private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));create policy "staff read vendor invoices" on storage.objects for select to authenticated using(bucket_id='vendor-invoices' and private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));
create or replace function public.receive_purchase_order_line(p_line_id uuid,p_quantity numeric,p_location_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_line public.purchase_order_items%rowtype;v_po public.purchase_orders%rowtype;v_tx uuid;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;if p_quantity<=0 then raise exception 'quantity must be positive';end if;select * into v_line from public.purchase_order_items where id=p_line_id for update;if v_line.id is null or v_line.inventory_item_id is null then raise exception 'invalid PO line';end if;if v_line.received_quantity+p_quantity>v_line.quantity then raise exception 'cannot receive more than ordered';end if;select * into v_po from public.purchase_orders where id=v_line.purchase_order_id for update;if not exists(select 1 from public.purchase_order_documents d where d.purchase_order_id=v_po.id and d.document_type='vendor_invoice') then raise exception 'vendor invoice photo or PDF is required before receiving material';end if;update public.purchase_order_items set received_quantity=received_quantity+p_quantity where id=v_line.id;update public.inventory_items set on_hand=on_hand+p_quantity,unit_cost=v_line.unit_cost,location_id=p_location_id where id=v_line.inventory_item_id;insert into public.inventory_transactions(inventory_item_id,location_id,purchase_order_id,transaction_type,quantity,unit_cost,actor_user_id) values(v_line.inventory_item_id,p_location_id,v_po.id,'receive',p_quantity,v_line.unit_cost,v_user.id) returning id into v_tx;update public.purchase_orders p set status=case when not exists(select 1 from public.purchase_order_items li where li.purchase_order_id=p.id and li.received_quantity<li.quantity) then 'received' else 'partial' end,received_at=case when not exists(select 1 from public.purchase_order_items li where li.purchase_order_id=p.id and li.received_quantity<li.quantity) then now() else p.received_at end where p.id=v_po.id;return v_tx;end$$;
